func suppressionMeta(r Suppression) string {
	if r.Reason == SuppressUnsubscribed {
		return "unsubscribed " + r.CreatedAt.Format("2 Jan 2006")
	}
	return "added by " + actorLabel(r.By) + " " + r.CreatedAt.Format("2 Jan 2006")
}

